package com.termux.app.terminal;
import android.app.Application;import com.termux.app.TermuxActivity;import com.termux.terminal.TerminalSession;import org.junit.Test;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowToast;import org.robolectric.util.ReflectionHelpers;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class) public class SessionTitleToastTest {
 @Test public void titleAndSwitchDoNotShowLegacyTopToastButGeneralNoticesRemain(){TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();ReflectionHelpers.setField(a,"mIsVisible",true);TermuxTerminalSessionClient client=new TermuxTerminalSessionClient(a);ShadowToast.reset();client.notifyOfSessionChange();TerminalSession session=new TerminalSession("unused","unused",new String[0],new String[0],2000,null);session.mSessionName="termux-fork";client.onTitleChanged(session);client.notifyOfSessionChange();assertEquals(0,ShadowToast.shownToastCount());assertEquals("termux-fork",session.mSessionName);a.showToast("Synthetic error notice",false);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals("Synthetic error notice",ShadowToast.getTextOfLatestToast());a.finish();}
}
